from scipy.optimize import least_squares
import warnings; warnings.filterwarnings('ignore')
t=np.asarray(t); A=np.asarray(A); y=np.asarray(dA_dt)
forms={
 'A^p': lambda p: p[3]*A**p[4],
 't^p': lambda p: p[3]*t**p[4],
 'exp(-pA)': lambda p: p[3]*np.exp(-np.abs(p[4])*A),
 'exp(-pt)': lambda p: p[3]*np.exp(-np.abs(p[4])*t),
 'A^p exp(-qt)': lambda p: p[3]*A**p[4]*np.exp(-np.abs(p[5])*t),
 'A^p t^q': lambda p: p[3]*A**p[4]*t**p[5],
}
lines=[]
for name,f in forms.items():
    best=None
    for s in range(30):
        x0=np.random.RandomState(s).uniform(-1,2,6)
        x0[2]=abs(x0[2])+0.01
        def fun(p):
            v=p[0]/t + p[1]*np.log(1+np.abs(p[2])*t)*A**2 + f(p)-y
            return np.nan_to_num(v,nan=1e6,posinf=1e6,neginf=-1e6)
        try:
            r=least_squares(fun, x0)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
    lines.append(f"{name} cost={best.cost:.4f} NMSE={np.var(best.fun)/np.var(y):.4g} p={np.round(best.x,4)}")
print("\n".join(lines))

